function CountPrimes(num: string): int
    requires num != null
    ensures CountPrimes(num) >= 0
{
    var count := 0;
    var i := 0;
    while i < num.Length
        invariant 0 <= i <= num.Length
        invariant count >= 0
    {
        if IsPrimeHexDigit(num[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function IsPrimeHexDigit(c: char): bool
